function group(a){if(window.PANDA_EDUCATION_095.some(g=>g.category===a.category))return a.category;if(legacyGroups[a.id])return legacyGroups[a.id];return /nutrition/i.test(a.category)?'Nutrition Fundamentals':/training/i.test(a.category)?'Training Education':/recovery/i.test(a.category)?'Recovery & Lifestyle':/mindset|lifestyle/i.test(a.category)?'Mindset & Consistency':'Progress Tracking';}
const weekdays=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
